// guardedBookRepository keeps Book's references whole; see guard.
type guardedBookRepository struct {
	BookRepository
	refs *repox.References
}

func (g *guardedBookRepository) Delete(ctx context.Context, name string) error {
	check, err := g.refs.CheckDelete(ctx, "catalog.example.com/Book", name)
	if err != nil {
		return err
	}
	if err := g.BookRepository.Delete(ctx, name); err != nil {
		return err
	}
	check.Done(ctx, false)
	return nil
}

// resolveBookReferences proves, through refs, that every external
// reference m sets within paths (all of them for an empty mask) names a
// resource that exists.
func resolveBookReferences(ctx context.Context, refs *repox.References, m *refdemov1.Book, paths []string) error {
	return nil
}

// queueBookReferences makes u resolve m's external references within
// paths before it commits, as guard does for the repositories.
func queueBookReferences(u *repox.Unit, m *refdemov1.Book, paths []string) {
}

// queueBookDelete makes u consult name's referrers before it commits
// and publish the NOTIFY event after, as guard does for Delete.
func queueBookDelete(u *repox.Unit, name string, purged bool) {
	refs := u.Conn().References
	if refs == nil {
		return
	}
	var check *repox.DeleteCheck
	u.Before(func(ctx context.Context) (err error) {
		check, err = refs.CheckDelete(ctx, "catalog.example.com/Book", name)
		return err
	})
	u.After(func(ctx context.Context) { check.Done(ctx, purged) })
}

// queueBookPurge makes u ask name's referrers before it commits; the
// purge it queues keeps the row when *keep is true.
func queueBookPurge(u *repox.Unit, name string) (keep *bool) {
	keep = new(bool)
	if refs := u.Conn().References; refs != nil {
		u.Before(func(ctx context.Context) error {
			*keep = refs.KeepOnPurge(ctx, "catalog.example.com/Book", name)
			return nil
		})
	}
	return keep
}

